  const weight = n => {
    const digits = String(Math.abs(n));
    let sum = 0;
    for (let i = 0; i < digits.length; i++) {
      const d = Number(digits[i]);
      if (n < 0 && i === 0) sum -= d;
      else sum += d;
    }
    return sum;
  };
  return values
    .map((v, i) => ({ v, i, w: weight(v) }))
    .sort((a, b) => a.w - b.w || a.i - b.i)
    .map(x => x.v);
}

