  function distinctCount(w) {
    const set = new Set();
    for (let i = 0; i < w.length; i++) set.add(w[i]);
    return set.size;
  }
  let best = words[0];
  let bestCount = distinctCount(best);
  for (let i = 1; i < words.length; i++) {
    const w = words[i];
    const c = distinctCount(w);
    if (c > bestCount || (c === bestCount && w < best)) {
      best = w;
      bestCount = c;
    }
  }
  return best;
}

