function solve([grid, k]) {
  const n = grid.length;
  const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  const total = n * n;

  if (k === 1) {
    let min = Infinity;
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        if (grid[r][c] < min) min = grid[r][c];
      }
    }
    return [min];
  }

  const pos = new Array(total + 1);
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      pos[grid[r][c]] = [r, c];
    }
  }

  function neighbors(v) {
    const [r, c] = pos[v];
    const res = [];
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        res.push(grid[nr][nc]);
      }
    }
    return res;
  }

  let best = null;

  function better(a, b) {
    if (b === null) return true;
    for (let i = 0; i < a.length; i++) {
      if (a[i] < b[i]) return true;
      if (a[i] > b[i]) return false;
    }
    return false;
  }

  function dfs(path) {
    if (path.length === k) {
      if (better(path, best)) best = path.slice();
      return;
    }
    if (best !== null) {
      for (let i = 0; i < path.length; i++) {
        if (path[i] < best[i]) break;
        if (path[i] > best[i]) return;
      }
    }
    const last = path[path.length - 1];
    const nbrs = neighbors(last);
    nbrs.sort((a, b) => a - b);
    for (const v of nbrs) {
      path.push(v);
      dfs(path);
      path.pop();
    }
  }

  for (let v = 1; v <= total; v++) {
    dfs([v]);
  }

  return best;
}

