function solve([grid, k]) {
  const n = grid.length;
  const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  let frontier = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      frontier.push({ r, c, path: [grid[r][c]] });
    }
  }
  for (let step = 1; step < k; step++) {
    let minNext = Infinity;
    for (const state of frontier) {
      const val = grid[state.r][state.c];
      if (val < minNext) minNext = val;
    }
    const nextFrontier = [];
    for (const state of frontier) {
      if (grid[state.r][state.c] !== minNext) continue;
      for (const [dr, dc] of dirs) {
        const nr = state.r + dr;
        const nc = state.c + dc;
        if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
        nextFrontier.push({ r: nr, c: nc, path: state.path.concat(grid[nr][nc]) });
      }
    }
    frontier = nextFrontier;
  }
  frontier.sort((a, b) => {
    for (let i = 0; i < k; i++) {
      if (a.path[i] !== b.path[i]) return a.path[i] - b.path[i];
    }
    return 0;
  });
  return frontier[0].path;
}

