  for (let step = 0; step < k; step++) {
    let minNext = Infinity;
    for (const state of frontier) {
      if (state.path[step] < minNext) minNext = state.path[step];
    }
    const nextFrontier = [];
    const seen = new Set();
    for (const state of frontier) {
      if (state.path[step] !== minNext) continue;
      if (step === k - 1) {
        return state.path;
      }
      const { r, c } = state;
      for (const [dr, dc] of dirs) {
        const nr = r + dr;
        const nc = c + dc;
