  for (let j = c - 1; j >= 0; j--) {
    suffixClose[j] = suffixClose[j + 1] + 1;
  }
  for (let a = 0; a < m; a++) {
    for (let b = a + 1; b < m; b++) {
      const i1 = open[a];
      const i2 = open[b];
      let j1 = -1;
      for (let k = 0; k < c; k++) {
        if (close[k] > i1) { j1 = k; break; }
      }
      if (j1 === -1) continue;
      const c1 = close[j1];
      if (c1 >= i2) continue;
      let j2 = -1;
      for (let k = j1 + 1; k < c; k++) {
        if (close[k] > i2) { j2 = k; break; }
      }
      if (j2 === -1) continue;
      return true;
    }
  }
  return false;
}

function solve(args) {
  const string = args[0];
  const n = string.length;
  const open = [];
  const close = [];
  for (let i = 0; i < n; i++) {
    if (string[i] === '[') open.push(i);
    else if (string[i] === ']') close.push(i);
  }
  const m = open.length;
  const c = close.length;
  for (let a = 0; a < m; a++) {
    for (let b = a + 1; b < m; b++) {
      const i1 = open[a];
      const i2 = open[b];
      let j1 = -1;
      for (let k = 0; k < c; k++) {
        if (close[k] > i1) { j1 = k; break; }
      }
      if (j1 === -1) continue;
      const c1 = close[j1];
      if (c1 >= i2) continue;
      let j2 = -1;
      for (let k = j1 + 1; k < c; k++) {
        if (close[k] > i2) { j2 = k; break; }
      }
      if (j2 === -1) continue;
      return true;
    }
  }
  return false;
}
